"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81134"],{93440(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.forma_de_avaliacao_desconhecida","status":422,"titulo":"A forma de avalia\xe7\xe3o declarada n\xe3o existe: use OBJETIVA ou HUMANA"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.forma_de_avaliacao_desconhecida","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["Uma das etapas do corpo do pedido informou `formaDeAvaliacao` com um texto que n\xe3o \xe9 uma das\\nduas formas existentes. A forma diz como a nota da etapa \xe9 obtida: **OBJETIVA** (corrigida\\npor gabarito ou leitora \xf3ptica, sem avaliador) ou **HUMANA** (as pessoas da banca da etapa\\nlan\xe7am as notas). A dupla corre\xe7\xe3o n\xe3o \xe9 uma terceira forma: ela qualifica a avalia\xe7\xe3o\\nhumana e \xe9 declarada pela regra de consolida\xe7\xe3o.","O sistema recusa o texto desconhecido em vez de trat\xe1-lo como campo em branco, porque um\\nerro de digita\xe7\xe3o passaria por etapa sem forma declarada e s\xf3 seria apontado na\\npublica\xe7\xe3o, longe de quem o cometeu. A recusa chega no array `errors[]`, no campo\\n`formaDeAvaliacao` da etapa, junto das demais viola\xe7\xf5es da mesma defini\xe7\xe3o de etapas."],"comoResolver":["Informe exatamente `OBJETIVA` ou `HUMANA`, em mai\xfasculas, ou omita o campo enquanto o\\nprocesso estiver em rascunho e a forma ainda n\xe3o tiver sido decidida.","A forma \xe9 obrigat\xf3ria s\xf3 na publica\xe7\xe3o, e s\xf3 na etapa com nota que n\xe3o \xe9 do ENEM. Se a\\nresposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);